#import "TFAIDirectoryRegistry.h"
#import "TFAIAttachmentStore.h"
static NSError *RError(NSString *message){return [NSError errorWithDomain:@"Dylix.DirectoryRegistry" code:1 userInfo:@{NSLocalizedDescriptionKey:message}];}
static NSString *RegistryPath(void){return [NSSearchPathForDirectoriesInDomains(NSApplicationSupportDirectory,NSUserDomainMask,YES).firstObject.stringByResolvingSymlinksInPath stringByAppendingPathComponent:@"Dylix/DirectoryRegistry.plist"];}
static BOOL Persist(NSArray *entries,NSError **error){NSString *path=RegistryPath();if(![path isEqual:path.stringByResolvingSymlinksInPath]){if(error)*error=RError(@"目录登记文件不允许符号链接");return NO;}if(![NSFileManager.defaultManager createDirectoryAtPath:path.stringByDeletingLastPathComponent withIntermediateDirectories:YES attributes:@{NSFilePosixPermissions:@0700} error:error])return NO;NSData *data=[NSPropertyListSerialization dataWithPropertyList:entries format:NSPropertyListBinaryFormat_v1_0 options:0 error:error];BOOL ok=[data writeToFile:path options:NSDataWritingAtomic error:error];if(ok)[NSFileManager.defaultManager setAttributes:@{NSFilePosixPermissions:@0600} ofItemAtPath:path error:nil];return ok;}
@implementation TFAIDirectoryRegistry
+ (NSArray *)entries{@synchronized(self){id value=[NSArray arrayWithContentsOfFile:RegistryPath()];if(![value isKindOfClass:NSArray.class])return @[];NSMutableArray *out=[NSMutableArray new];for(id row in value)if([row isKindOfClass:NSDictionary.class]&&[[NSUUID alloc]initWithUUIDString:row[@"directoryGrant"]]){NSMutableDictionary *item=[row mutableCopy];item[@"available"]=@(TFAIReadDirectoryReference(row,@{@"action":@"validate"},nil)!=nil);[out addObject:item];if(out.count==10)break;}return out;}}
+ (NSDictionary *)add:(NSURL *)url error:(NSError **)error{@synchronized(self){NSArray *old=[self entries];if(old.count>=10){if(error)*error=RError(@"最多登记10个目录，请先撤销不用的目录。");return nil;}BOOL scope=[url startAccessingSecurityScopedResource];@try{NSString *path=url.path.stringByStandardizingPath.stringByResolvingSymlinksInPath;NSString *selected=url.path.stringByStandardizingPath;if(![path isEqual:selected]&&[selected hasPrefix:@"/var/"])selected=[@"/private" stringByAppendingString:selected];if(!url.isFileURL||![path isEqual:selected]){if(error)*error=RError(@"请选择真实目录，不跟随符号链接。");return nil;}for(NSDictionary *row in old){NSURL *other=TFAIDirectoryBrowserURL(row,nil);if(!other)continue;BOOL access=[other startAccessingSecurityScopedResource];NSString *base=other.path.stringByStandardizingPath.stringByResolvingSymlinksInPath;BOOL overlap=[base isEqual:path]||[base hasPrefix:[path stringByAppendingString:@"/"]]||[path hasPrefix:[base stringByAppendingString:@"/"]];if(access)[other stopAccessingSecurityScopedResource];if(overlap){if(error)*error=RError(@"与已登记目录重叠，请使用现有授权。");return nil;}}NSDictionary *entry=TFAIAuthorizeDirectory(url,@"独立目录登记",error);if(!entry)return nil;NSMutableArray *next=[old mutableCopy];[next addObject:entry];if(!Persist(next,error)){TFAIRevokeDirectory(entry,nil);return nil;}return entry;}@finally{if(scope)[url stopAccessingSecurityScopedResource];}}}
+ (BOOL)remove:(NSString *)identifier error:(NSError **)error{@synchronized(self){NSMutableArray *next=[[self entries] mutableCopy];NSDictionary *selected=nil;for(NSDictionary *row in next)if([row[@"directoryGrant"] isEqual:identifier]){selected=row;break;}if(!selected)return YES;if(!TFAIRevokeDirectory(selected,error))return NO;[next removeObject:selected];return Persist(next,error);}}
@end
